    <script>
        let neurons = [];
        let connections = [];
        let params = {
            neuronCount: 80,
            connectionRange: 150,
            threshold: 0.5,
            growthRate: 0.002,
            decayRate: 0.001,
            activityBoost: 1.0,
            colorTemp: 255
        };
        let frameCount = 0;
        let burstNeurons = [];
        let mousePos = createVector(0, 0);
        let isMouseDown = false;
        let noiseOffset = 0;

        class Neuron {
            constructor(x, y) {
                this.pos = createVector(x, y);
                this.velocity = p5.Vector.random2D().mult(random(0.5, 2));
                this.size = random(2, 5);
                this.activity = random(0.2, 0.8);
                this.baseActivity = this.activity;
                this.targetActivity = this.activity;
                this.connections = [];
                this.lastBurst = 0;
            }

            update() {
                this.pos.add(this.velocity);

                // Mouse attraction
                let distToMouse = p5.Vector.dist(this.pos, mousePos);
                if (distToMouse < 200) {
                    let dir = p5.Vector.sub(mousePos, this.pos);
                    let force = p5.Vector.normalize(dir).mult(0.05 / (distToMouse / 200));
                    this.velocity.add(force);
                }

                // Friction
                this.velocity.mult(0.98);

                // Return to center (core)
                let center = createVector(width/2, height/2);
                let distToCenter = p5.Vector.dist(this.pos, center);
                if (distToCenter > 50) {
                    let dir = p5.Vector.sub(center, this.pos);
                    let force = p5.Vector.normalize(dir).mult(0.0005 * (distToCenter / 50));
                    this.velocity.add(force);
                }

                // Activity fluctuation
                this.targetActivity += (random(-0.01, 0.01) * params.activityBoost);
                this.activity = lerp(this.activity, this.targetActivity, 0.02);

                // Wrap around edges
                if (this.pos.x < 0) this.pos.x = width;
                if (this.pos.x > width) this.pos.x = 0;
                if (this.pos.y < 0) this.pos.y = height;
                if (this.pos.y > height) this.pos.y = 0;
            }

            draw() {
                let activityFactor = map(this.activity, 0, 1, 1.5, 0.5);
                this.size = map(this.size, 2, 5, this.size * activityFactor, this.size);

                // Color based on activity
                let r, g, b;
                if (this.activity > 0.8) {
                    // Neural burst
                    r = 200 + random(-30, 30);
                    g = 255;
                    b = 255;
                } else if (this.activity > 0.5) {
                    r = 123 + random(-20, 20);
                    g = 181 + random(-20, 20);
                    b = 255;
                } else {
                    r = 90 + random(-10, 10);
                    g = 90 + random(-10, 10);
                    b = 100 + random(-10, 10);
                }

                noStroke();
                fill(r, g, b, 150);
                ellipse(this.pos.x, this.pos.y, this.size);
            }
        }

        class Connection {
            constructor(n1, n2) {
                this.n1 = n1;
                this.n2 = n2;
                this.weight = random(0.1, 0.9);
                this.length = p5.Vector.dist(n1.pos, n2.pos);
            }

            update() {
                let dist = p5.Vector.dist(this.n1.pos, this.n2.pos);

                // Strengthen if both active
                let avgActivity = (this.n1.activity + this.n2.activity) / 2;
                this.weight += (avgActivity - this.weight) * params.growthRate;
                this.weight = constrain(this.weight, 0.01, 1);

                // Decay if inactive
                if (avgActivity < 0.3) {
                    this.weight -= params.decayRate;
                }

                // Remove very weak connections
                if (this.weight < 0.05) {
                    return false;
                }

                return true;
            }

            draw() {
                let weightFactor = map(this.weight, 0.05, 1, 0.3, 6);
                let distFactor = map(p5.Vector.dist(this.n1.pos, this.n2.pos), 0, params.connectionRange, 0.5, 1);

                let r, g, b, alpha;
                if (this.weight > 0.7) {
                    r = 255; g = 107; b = 107; // Strong = red
                } else if (this.weight > 0.33) {
                    r = 123; g = 181; b = 255; // Moderate = blue
                } else {
                    r = 90; g = 90; b = 100; // Weak = gray
                }

                alpha = map(this.weight, 0.05, 1, 20, 255);
                stroke(r, g, b, alpha);
                strokeWeight(weightFactor * distFactor);
                line(this.n1.pos.x, this.n1.pos.y, this.n2.pos.x, this.n2.pos.y);
            }
        }

        function setup() {
            let canvas = createCanvas(windowWidth, windowHeight);
            canvas.parent('canvas-container');
            pixels.enabled = true;

            for (let i = 0; i < params.neuronCount; i++) {
                let x = random(width);
                let y = random(height);
                neurons.push(new Neuron(x, y));
            }

            updateStats();
        }

        function draw() {
            frameCount++;
            noiseOffset += 0.003;

            // Fade effect
            for (let i = 0; i < width * height; i++) {
                if (random() < 0.02) {
                    pixels[i] = color(5, 5, 8);
                }
            }
            updatePixels();

            // Draw connections
            for (let i = 0; i < neurons.length; i++) {
                for (let j = i + 1; j < neurons.length; j++) {
                    let n1 = neurons[i];
                    let n2 = neurons[j];

